// هذا الكود بيحمّل الملف الخام من الرابط الموقّع (Signed URL) اللي بعته
// الفرونت إند (مالوش داعي أي مصادقة إضافية لأن التوكن جوه الرابط نفسه)،
// وبعدين لو الملف Word أو PowerPoint، بيستخرج النص منه يدويًا (الملفين دول
// أصلهم أرشيف ZIP فيه ملفات XML - بنفك الضغط ونقرأ الـ XML بكود بسيط من
// غير أي مكتبات خارجية، لأن كل اللي محتاجينه (zlib) مدمج في Node أصلًا).
// لو الملف PDF، منعملش استخراج يدوي خالص - بنسيب Gemini يقرأ الـ PDF
// مباشرة (بيدعم PDF بشكل أصلي وبيفهم شكل الصفحات والفصول بنفسه، ده أدق
// بكتير من أي استخراج نصوص يدوي لملفات PDF).
const zlib = require('zlib');

const teacherId = $('Decode JWT').item.json.teacherId;
const bookId = $('Decode JWT').item.json.bookId;
const fileUrl = $('Decode JWT').item.json.fileUrl;
const fileType = $('Get Book').item.json.file_type;
const title = $('Get Book').item.json.title;

if (!fileUrl) {
  throw new Error('MISSING_FILE_URL: الفرونت إند لازم يبعت رابط الملف الموقّع بعد رفعه لـ Supabase Storage.');
}

let fileBuffer;
try {
  const response = await this.helpers.httpRequest({
    url: fileUrl,
    method: 'GET',
    encoding: 'arraybuffer',
    returnFullResponse: false
  });
  fileBuffer = Buffer.isBuffer(response) ? response : Buffer.from(response);
} catch (e) {
  throw new Error('DOWNLOAD_FAILED: تعذّر تحميل الملف من التخزين - ' + e.message);
}

// -------- استخراج نصوص من ملفات ZIP (Word/PowerPoint) --------
function findEOCD(buf) {
  const searchWindow = Math.min(buf.length, 66000);
  const start = buf.length - searchWindow;
  for (let i = buf.length - 22; i >= start; i--) {
    if (buf.readUInt32LE(i) === 0x06054b50) return i;
  }
  throw new Error('EOCD_NOT_FOUND: الملف تالف أو مش أرشيف ZIP سليم (docx/pptx غير صالح؟)');
}

function listZipEntries(buf) {
  const eocdOffset = findEOCD(buf);
  const totalEntries = buf.readUInt16LE(eocdOffset + 10);
  let cdOffset = buf.readUInt32LE(eocdOffset + 16);
  const entries = [];
  for (let i = 0; i < totalEntries; i++) {
    const sig = buf.readUInt32LE(cdOffset);
    if (sig !== 0x02014b50) break;
    const compressionMethod = buf.readUInt16LE(cdOffset + 10);
    const compressedSize = buf.readUInt32LE(cdOffset + 20);
    const fileNameLength = buf.readUInt16LE(cdOffset + 28);
    const extraLength = buf.readUInt16LE(cdOffset + 30);
    const commentLength = buf.readUInt16LE(cdOffset + 32);
    const localHeaderOffset = buf.readUInt32LE(cdOffset + 42);
    const fileName = buf.toString('utf8', cdOffset + 46, cdOffset + 46 + fileNameLength);
    entries.push({ fileName, compressionMethod, compressedSize, localHeaderOffset });
    cdOffset += 46 + fileNameLength + extraLength + commentLength;
  }
  return entries;
}

function readZipEntryContent(buf, entry) {
  const lh = entry.localHeaderOffset;
  if (buf.readUInt32LE(lh) !== 0x04034b50) throw new Error('LOCAL_HEADER_INVALID');
  const fileNameLength = buf.readUInt16LE(lh + 26);
  const extraLength = buf.readUInt16LE(lh + 28);
  const dataStart = lh + 30 + fileNameLength + extraLength;
  const compressed = buf.slice(dataStart, dataStart + entry.compressedSize);
  if (entry.compressionMethod === 0) return compressed;
  if (entry.compressionMethod === 8) return zlib.inflateRawSync(compressed);
  throw new Error('UNSUPPORTED_COMPRESSION_METHOD_' + entry.compressionMethod);
}

function xmlToPlainText(xml) {
  return xml
    .replace(/<\/w:p>/g, '\n')
    .replace(/<\/a:p>/g, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"').replace(/&apos;/g, "'")
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function extractDocx(buf) {
  const entries = listZipEntries(buf);
  const docEntry = entries.find(e => e.fileName === 'word/document.xml');
  if (!docEntry) throw new Error('DOCX_MISSING_DOCUMENT_XML: تعذّر إيجاد محتوى الملف - تأكدي إنه ملف Word سليم (.docx)');
  const xmlBuf = readZipEntryContent(buf, docEntry);
  return xmlToPlainText(xmlBuf.toString('utf8'));
}

function extractPptx(buf) {
  const entries = listZipEntries(buf);
  const slideEntries = entries
    .filter(e => /^ppt\/slides\/slide\d+\.xml$/.test(e.fileName))
    .map(e => ({ ...e, num: parseInt(e.fileName.match(/slide(\d+)\.xml/)[1]) }))
    .sort((a, b) => a.num - b.num);
  if (slideEntries.length === 0) throw new Error('PPTX_NO_SLIDES: تعذّر إيجاد أي شرائح - تأكدي إنه ملف PowerPoint سليم (.pptx)');
  return slideEntries.map(e => {
    const xmlBuf = readZipEntryContent(buf, e);
    const text = xmlToPlainText(xmlBuf.toString('utf8'));
    return `--- شريحة ${e.num} ---\n${text}`;
  }).join('\n\n');
}

let geminiContentPart;
if (fileType === 'pdf') {
  geminiContentPart = { inlineData: { mimeType: 'application/pdf', data: fileBuffer.toString('base64') } };
} else if (fileType === 'docx') {
  const text = extractDocx(fileBuffer);
  geminiContentPart = { text: text.slice(0, 400000) };
} else if (fileType === 'pptx') {
  const text = extractPptx(fileBuffer);
  geminiContentPart = { text: text.slice(0, 400000) };
} else {
  throw new Error('UNSUPPORTED_FILE_TYPE: ' + fileType);
}

const analysisPrompt = `أنت مساعد بيحلل مصدر تعليمي (كتاب/مذكرة) رفعه معلم. اسم الملف كما أدخله المعلم: "${title}".

مهمتك: اقرأ المحتوى المرفق بالكامل واستخرج منه:
1. عنوان الكتاب الحقيقي (لو ظاهر في المحتوى، وإلا استخدم الاسم المُعطى).
2. تقدير عدد الصفحات (لو المحتوى PDF قدّر من عدد الصفحات الفعلي؛ لو مستند Word/PowerPoint قدّر تقديرًا معقولًا بناءً على طول المحتوى، بمعدل ~300 كلمة للصفحة).
3. قائمة الفصول/الأقسام الرئيسية بعناوينها.
4. تقسيم المحتوى بالكامل إلى مقاطع (chunks) متتالية، كل مقطع بين 100 و300 كلمة تقريبًا، بحيث يمثل فكرة أو جزء متماسك، مع تحديد اسم الفصل الذي ينتمي إليه كل مقطع، ورقم الصفحة التقريبي له إن أمكن (استخدم null لو مش معروف).

أعد الناتج بصيغة JSON فقط بدون أي نص إضافي، بالشكل التالي بالظبط:
{
  "title": "...",
  "page_count": 0,
  "chapters": [{"title": "..."}],
  "chunks": [{"chapter": "...", "page": 0, "content": "..."}]
}`;

const geminiRequestBody = {
  contents: [{ role: 'user', parts: [{ text: analysisPrompt }, geminiContentPart] }],
  generationConfig: { temperature: 0.2, maxOutputTokens: 8192, responseMimeType: 'application/json' }
};

return { teacherId, bookId, title, fileType, geminiRequestBody };

const prev = $('Download & Prepare Content').item.json;
const raw = $input.first().json;

function failItem(message) {
  return [{ json: { itemType: 'error', bookId: prev.bookId, teacherId: prev.teacherId, errorMessage: message } }];
}

if (raw.error) {
  return failItem('تعذّر تحليل الملف عبر الذكاء الاصطناعي: ' + JSON.stringify(raw.error).slice(0, 300));
}

const candidate = raw.candidates && raw.candidates[0];
const text = candidate && candidate.content && candidate.content.parts && candidate.content.parts[0] && candidate.content.parts[0].text;
if (!text) {
  return failItem('لم يرجّع الذكاء الاصطناعي أي محتوى قابل للتحليل لهذا الملف.');
}

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  return failItem('تعذّر فهم استجابة تحليل الملف (تنسيق غير صالح).');
}

const chunks = Array.isArray(parsed.chunks) ? parsed.chunks.filter(c => c && c.content && c.content.toString().trim()) : [];
if (chunks.length === 0) {
  return failItem('لم يتم استخراج أي محتوى قابل للفهرسة من هذا الملف.');
}

const chapters = Array.isArray(parsed.chapters) ? parsed.chapters : [];
const items = [];
items.push({
  json: {
    itemType: 'summary',
    bookId: prev.bookId,
    teacherId: prev.teacherId,
    title: (parsed.title || prev.title || '').toString().slice(0, 200),
    pageCount: parseInt(parsed.page_count) || null,
    chapterCount: chapters.length,
    chaptersJson: JSON.stringify(chapters)
  }
});
chunks.forEach((c, i) => {
  items.push({
    json: {
      itemType: 'chunk',
      bookId: prev.bookId,
      teacherId: prev.teacherId,
      chunkIndex: i,
      chapter: (c.chapter || '').toString().slice(0, 200) || null,
      page: c.page ? parseInt(c.page) : null,
      content: c.content.toString().slice(0, 4000)
    }
  });
});
return items;

