const chunkData = $('Is Chunk?').item.json;
const raw = $input.first().json;

const values = raw && raw.embedding && Array.isArray(raw.embedding.values) ? raw.embedding.values : null;
if (!values) {
  // فشل embedding المقطع ده تحديدًا - نتجاهله بدل ما نكسر باقي الكتاب
  return [];
}

return [{
  json: {
    bookId: chunkData.bookId,
    teacherId: chunkData.teacherId,
    chunkIndex: chunkData.chunkIndex,
    chapter: chunkData.chapter,
    page: chunkData.page,
    content: chunkData.content,
    embeddingLiteral: '[' + values.join(',') + ']'
  }
}];
